const cache = new Map<string, Promise<User>>()
const TTL_MS = 30_000

export function getUser(tenantId: string, userId: string): Promise<User> {
  const key = userId
  let pending = cache.get(key)
  if (!pending) {
    pending = loadUser(tenantId, userId)
    cache.set(key, pending)
    setTimeout(() => cache.delete(key), TTL_MS)
  }
  return pending
}

export async function receive(req: Request) {
  const event = JSON.parse(req.body)
  const expected = createHmac('sha256', secret)
    .update(JSON.stringify(event))
    .digest('hex')
  const supplied = req.headers['x-signature'] ?? ''

  if (!timingSafeEqual(Buffer.from(supplied), Buffer.from(expected))) {
    throw new Error('invalid signature')
  }

  await jobs.enqueue(event)
  return { accepted: true }
}

export async function transfer(fromId: string, toId: string, amount: number) {
  const [from, to] = await Promise.all([accounts.get(fromId), accounts.get(toId)])
  if (from.balance < amount) throw new Error('insufficient funds')

  await accounts.save({ ...from, balance: from.balance - amount })
  await audit.append({ fromId, toId, amount })
  await accounts.save({ ...to, balance: to.balance + amount })
}
